class GSLVector:
    def __init__(self, data):
        self.data = (ctypes.c_double * len(data))(*data)

    def get_data(self):
        return list(self.data)

    @staticmethod
def vector_add(a, b):
    if len(a.get_data()) != len(b.get_data()):
        raise ValueError("Vectors must have the same length")
    result = [0.0] * len(a.get_data())
    for i in range(len(a.get_data())):
        result[i] = a.get_data()[i] + b.get_data()[i]
    return GSLVector(result)

