def prime_factors(num):
    factors = []
    divisor = 2
    while num > 1:
        if num % divisor == 0:
            factors.append(divisor)
            num //= divisor
        else:
            divisor += 1
    return factors, len(factors)

def fft_factorize(n):
    result = gsl.gsl_factorize(ctypes.c_longlong(n))
