        return gsl.gsl_matrix_alloc(float_ptr_t(np_array.size), ctypes.c_size_t(np_array.shape[1])), float_ptr_t.from_buffer(np_array)
    else:
        raise TypeError("Unsupported data type")

def copy_matrix(dest, src):
    if dest.size1 != src.size1 or dest.size2 != src.size2:
        raise ValueError("Matrices must have the same dimensions")
    return gsl.gsl_matrix_memcpy(ctypes.byref(dest), ctypes.byref(src))

