class GSLFunction:
    def __init__(self, func):
        self.func = func
        self.wrapper_func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.py_object)(self.wrapper)

    def wrapper(self, x, params=None):
        return self.func(x)

