    gsl_function = GSLFunction(func).wrapper_func
    result = ctypes.c_double()
    abserr = ctypes.c_double()
    params = None  # No additional parameters needed in this case
    status = gsl.gsl_integration_qc25c(gsl_function, a, b, c, abserr, result, params)
    return result.value, abserr.value, status != 0

