    n = len(data)
    block = allocate_float_block(n)
    for i, value in enumerate(data):
        block[i] = ctypes.c_double(value * 2)  # Example modification: double each value
    result = [block[i].value for i in range(n)]
    gsl.gsl_vector_free(block)
    return result

