class GSLFilterGaussianWorkspace:
    def __init__(self, size, alpha):
        self.workspace = gsl.gsl_filter_gaussian_alloc(size, alpha)

    def apply(self, input_vector, output_vector, derivative1_vector, derivative2_vector):
        gsl.gsl_filter_gaussian_apply(self.workspace, input_vector.vector, input_vector.vector.size,
                                     output_vector.vector, derivative1_vector.vector, derivative2_vector.vector)

