    'linear': gsl.interp_linear,
    'cspline': gsl.interp_cspline,
    # Add more as needed
}

def allocate_spline(interpolation_type, size):
    if interpolation_type not in interp_types:
        raise ValueError("Unsupported interpolation type")

    interp_type_name = ctypes.c_char_p(interp_types[interpolation_type].encode('utf-8'))
    size_c = ctypes.c_size_t(size)

    # Allocate the spline object
    try:
        allocate_func = gsl.gsl_spline_alloc
        allocate_func.argtypes = [ctypes.POINTER(gsl_interp_type), ctypes.c_size_t]
        allocate_func.restype = ctypes.POINTER(gsl_spline)
        spline_ptr = allocate_func(interp_type_name, size_c)

        if not spline_ptr:
            raise RuntimeError("Failed to allocate spline object")

        return spline_ptr
    except Exception as e:
        print(f"Error allocating spline: {e}")
        return None

