import numpy as np
from scipy.linalg import lapack_lite

def compute_eigenvalues(A, B):
    if not isinstance(A, np.ndarray) or not isinstance(B, np.ndarray):
        raise ValueError('Input matrices must be NumPy arrays')
    if A.dtype != 'complex128' or B.dtype != 'complex128':
        raise ValueError('Input matrices must be complex numbers')
    if A.shape[0] != A.shape[1] or B.shape[0] != B.shape[1]:
        raise ValueError('Input matrices must be square')
    if A.shape[0] != B.shape[0]:
        raise ValueError('Input matrices must have the same dimensions')

    n = A.shape[0]
    gsl_A = lapack_lite.dggev(A, B)

    eigenvalues = np.empty(n, dtype=np.complex128)
    for i in range(n):
        eigenvalues[i] = complex(gsl_A['w'][i].real, gsl_A['w'][i].imag)

    return eigenvalues

