gsl = load_gsl_libraries()

def compute_pooled_variance(data1, stride1, n1, data2, stride2, n2):
    if not isinstance(data1, list) or not isinstance(data2, list):
        raise ValueError("Both datasets must be lists.")

    if not all(isinstance(i, (int, float)) for i in data1 + data2):
        raise ValueError("All elements in the datasets must be numbers.")

    if stride1 <= 0 or stride2 <= 0:
        raise ValueError("Strides must be positive integers.")

    if n1 <= 0 or n2 <= 0:
        raise ValueError("Dataset sizes must be greater than zero.")

    data1_arr = (ctypes.c_double * len(data1))(*data1)
    data2_arr = (ctypes.c_double * len(data2))(*data2)

    result = gsl.gsl_stats_pvariance(data1_arr, stride1, n1, data2_arr, stride2, n2)

    return float(result)

