cdef generate_reverse_halton(dimension, num_points):
    if dimension < 1 or dimension > 1229:
        raise ValueError("Invalid dimension. Must be between 1 and 1229.")

    cdef gsl_rng *rng = gsl.gsl_rng_alloc(gsl.GSL_RNG_TYPE_DEFAULT)
    gsl.gsl_rng_set_seed(rng, 0)

    cdef double *points = <double *>malloc(num_points * dimension * sizeof(double))
    if points == NULL:
        raise MemoryError("Failed to allocate memory for points.")

    try:
        for i in range(num_points):
            for j in range(dimension):
                cdef double value = 1.0 / (j + 2)
                while value > 0.0:
                    if gsl.gsl_rng_uniform(rng) < value:
                        points[i * dimension + j] += value
                    value /= 2.0
    finally:
        free(points)

    cdef list result = []
    for i in range(num_points):
        result.append([points[i * dimension + j] for j in range(dimension)])

    gsl.gsl_rng_free(rng)
    return json.dumps(result)

