def set_ieee_mode(precision, rounding, exception_mask):
    precision_code = precisions.get(precision.lower(), None)
    rounding_code = roundings.get(rounding.lower(), None)
    exception_code = exceptions.get(exception_mask.lower(), None)

    if not all([precision_code, rounding_code, exception_code]):
        raise ValueError("Invalid precision, rounding mode, or exception mask")

    result = gsl.set_ieee_mode(precision_code, rounding_code, exception_code)
    return result

