class GSLFunction:
    def __init__(self, function):
        self.function = function

    def callback(self, x):
        return self.function(x)

class GSLIntegrationWorkspace:
    def integrate(self, function, a, b, epsabs, epsrel, limit, key):
        func_ptr = gsl.gsl_function()
        func_ptr.function = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(self.callback)
        func_ptr.data = None

        result = ctypes.c_double()
        abserr = ctypes.c_double()

        gsl.gsl_integration_qag(func_ptr, a, b, epsabs, epsrel, limit, key, None, ctypes.byref(result), ctypes.byref(abserr))

        return result.value, abserr.value

