class GSLVector:
    def __init__(self, data):
        self.data = data
        self.size = len(data)
        self.vector = gsl.gsl_vector_alloc(self.size)
        for i in range(self.size):
            gsl.gsl_vector_set(self.vector, i, data[i])

    def __del__(self):
        gsl.gsl_vector_free(self.vector)

def copy_gsl_vector(source_list, destination_list):
    source = GSLVector(source_list)
    destination = GSLVector(destination_list)
    for i in range(source.size):
        destination.data[i] = gsl.gsl_vector_get(source.vector, i)
    return destination.data

