GSL_SUCCESS = 0

class gsl_matrix(ctypes.Structure):
    _fields_ = ["data", "stride", "size1", "size2"]

class gsl_vector(ctypes.Structure):
    _fields_ = ["data", "stride", "size"]

def numpy_to_gsl_matrix(np_array):
    if np_array.ndim != 2:
        raise ValueError("Input array must be a 2D numpy array")
    matrix = gsl_matrix()
    matrix.data = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    matrix.stride = np_array.shape[1]
    matrix.size1 = np_array.shape[0]
    matrix.size2 = np_array.shape[1]
    return matrix

def numpy_to_gsl_vector(np_array):
    if np_array.ndim != 1:
        raise ValueError("Input array must be a 1D numpy array")
    vector = gsl_vector()
    vector.data = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    vector.stride = 1
    vector.size = np_array.shape[0]
    return vector

def hesstri_decomp(A, B, U=None, V=None, work=None):
    if A.ndim != 2 or B.ndim != 2:
        raise ValueError("Input arrays must be 2D numpy arrays")
    if A.shape != B.shape:
        raise ValueError("Input matrices must have the same dimensions")

    m, n = A.shape
    if U is None:
        U = np.eye(m)
    if V is None:
        V = np.eye(n)
    if work is None:
        work = np.empty(m)

    gsl_A = numpy_to_gsl_matrix(A)
    gsl_B = numpy_to_gsl_matrix(B)
    gsl_U = numpy_to_gsl_matrix(U)
    gsl_V = numpy_to_gsl_matrix(V)
    gsl_work = numpy_to_gsl_vector(work)

    result = gsl.gsl_linalg_hesstri_decomp(gsl_A, gsl_B, gsl_U, gsl_V, gsl_work)
    if result != GSL_SUCCESS:
        raise RuntimeError("Hessenberg-triangular decomposition failed")

    return A, B, U, V
