        self.func = func
        self.callback = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)
        self.callback_ptr = self.callback(self.f_wrapper)

    def f_wrapper(self, x, params):
        return self.func(x, params)

class GSLMinFMinimizer:
    def __init__(self, type_id, n):
        self.type_id = type_id
        self.n = n
        self.minimizer = gsl.gsl_min_fminimizer_alloc(ctypes.c_int(type_id), ctypes.c_size_t(n))

    def free(self):
        gsl.gsl_min_fminimizer_free(self.minimizer)

    def set(self, function, params, x_lower, f_lower, x_upper, f_upper):
        gsl.gsl_min_fminimizer_set(self.minimizer, function.callback_ptr, ctypes.c_double(x_lower), ctypes.c_double(f_lower), ctypes.c_double(x_upper), ctypes.c_double(f_upper))

    def iterate(self):
        return gsl.gsl_min_fminimizer_iterate(self.minimizer)

    def x_minimum(self):
        return self.minimizer.x

    def f_minimum(self):
        return self.minimizer.f

    def x_lower(self):
        return self.minimizer.x_lower

    def f_lower(self):
        return self.minimizer.f_lower

    def x_upper(self):
        return self.minimizer.x_upper

    def f_upper(self):
        return self.minimizer.f_upper

