ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

gsl.gsl_linalg_exponential_ss.argtypes = [POINTER(ctypes.c_double), POINTER(POINTER(ctypes.c_double)), ctypes.c_int, c_double]
gsl.gsl_linalg_exponential_ss.restype = None

GSLMatrix = np.ctypeslib.ndpointer(dtype=np.float64, ndim=2, flags='C_CONTIGUOUS')

def matrix_to_gsl(matrix: GSLMatrix) -> POINTER(POINTER(ctypes.c_double)):
    nrows, ncols = matrix.shape
    gsl_matrix = (ctypes.POINTER(ctypes.c_double) * nrows)()
    for i in range(nrows):
        gsl_matrix[i] = cast((ctypes.c_double * ncols).from_buffer(matrix[i]), POINTER(ctypes.c_double))
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix: POINTER(POINTER(ctypes.c_double)), nrows: int, ncols: int) -> np.ndarray:
    numpy_array = np.zeros((nrows, ncols), dtype=np.float64)
    for i in range(nrows):
        ctypes.memmove(numpy_array[i].ctypes.data_as(ctypes.POINTER(ctypes.c_double)), gsl_matrix[i], ncols * ctypes.sizeof(ctypes.c_double))
    return numpy_array

def compute_matrix_exponential(matrix: GSLMatrix, mode: int) -> np.ndarray:
    nrows, ncols = matrix.shape
    if nrows != ncols:
        raise ValueError("Input must be a square matrix")

    gsl_matrix = matrix_to_gsl(matrix)
    result_gsl_matrix = (ctypes.POINTER(ctypes.c_double) * nrows)()
    for i in range(nrows):
        result_gsl_matrix[i] = cast((ctypes.c_double * ncols).from_buffer(np.zeros(ncols, dtype=np.float64)), POINTER(ctypes.c_double))

    gsl.gsl_linalg_exponential_ss(gsl_matrix, result_gsl_matrix, mode, 0.0)

    return gsl_matrix_to_numpy(result_gsl_matrix, nrows, ncols)
