def matrix_to_gsl(matrix):
    rows, cols = len(matrix), len(matrix[0])
    gsl_matrix_type = gsl.matrix_t * (rows * cols)
    gsl_matrix_data = (ctypes.c_double * (rows * cols))(*sum(matrix, []))
    gsl_matrix = gsl_matrix_type.from_buffer(gsl_matrix_data)
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    rows, cols = int(gsl_matrix.size / gsl_matrix.tda), gsl_matrix.tda
    return np.frombuffer(gsl_matrix.data_as(ctypes.c_double_p), dtype=np.double).reshape(rows, cols)

def compute_matrix_exponential(matrix, mode):
    if not all(isinstance(row, list) and len(row) == len(matrix[0]) for row in matrix):
        raise ValueError("Input must be a square matrix.")

    gsl_matrix = matrix_to_gsl(matrix)
    result_matrix = gsl.matrix_t(gsl_matrix.size, gsl_matrix.tda)

    status = gsl.gsl_linalg_exponential_ss(ctypes.byref(gsl_matrix), mode, ctypes.byref(result_matrix))

    if status != 0:
        raise RuntimeError("GSL error occurred during matrix exponential computation.")

    return gsl_matrix_to_numpy(result_matrix)
