import numpy as np

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.rows = len(matrix)
        self.cols = len(matrix[0])

    def to_gsl(self):
        gsl_matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(gsl_matrix, i, j, self.matrix[i][j])
        return gsl_matrix

    def from_gsl(self, gsl_matrix):
        result = [[0.0] * self.cols for _ in range(self.rows)]
        for i in range(self.rows):
            for j in range(self.cols):
                result[i][j] = gsl.gsl_matrix_get(gsl_matrix, i, j)
        return result

def matrix_to_gsl(matrix):
    return GSLMatrix(matrix).to_gsl()

def gsl_matrix_to_numpy(gsl_matrix):
    rows = gsl.gsl_matrix_ptr(gsl_matrix, 0).data.contents.l.row
    cols = gsl.gsl_matrix_ptr(gsl_matrix, 0).data.contents.l.cols
    data = np.ctypeslib.ndpointer(dtype=np.float64, ndim=1, flags='C_CONTIGUOUS')
    ptr = data.from_address(id(gsl.gsl_matrix_ptr(gsl_matrix, 0).data.contents.data))
    return np.ascontiguousarray(ptr[:rows * cols].reshape(rows, cols), dtype=np.float64)

def compute_matrix_exponential(matrix, mode):
    try:
        gsl_matrix = matrix_to_gsl(matrix)
        result_matrix = gsl.gsl_linalg_exponential_ss(gsl_matrix, mode)
        return gsl_matrix_to_numpy(result_matrix)
    except Exception as e:
        print(f"Error computing matrix exponential: {e}")
        return None
