from ctypes import c_int, POINTER, c_double, cast

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.nrows = len(matrix)
        self.ncols = len(matrix[0])
        self.gsl_matrix = self.matrix_to_gsl(self.matrix)

    @staticmethod
def matrix_to_gsl(matrix):
        nrows = len(matrix)
        ncols = len(matrix[0])
        gsl_matrix = gsl.gsl_matrix_alloc(nrows, ncols)
        for i in range(nrows):
            for j in range(ncols):
                gsl.gsl_matrix_set(gsl_matrix, i, j, c_double(matrix[i][j]))
        return gsl_matrix

    @staticmethod
def gsl_matrix_to_numpy(gsl_matrix):
        nrows = gsl_matrix.gsl_matrix_size1
        ncols = gsl_matrix.gsl_matrix_size2
        matrix = np.zeros((nrows, ncols), dtype=np.double)
        for i in range(nrows):
            for j in range(ncols):
                matrix[i][j] = gsl.gsl_matrix_get(gsl_matrix, i, j)
        return matrix

def compute_matrix_exponential(matrix, mode=0):
    try:
        gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        nrows = len(matrix)
        ncols = len(matrix[0])
        if nrows != ncols:
            raise ValueError('Input matrix must be square')

        gsl_matrix = GSLMatrix(matrix).gsl_matrix
        result_gsl_matrix = gsl.gsl_matrix_alloc(nrows, ncols)
        gsl.gsl_linalg_exponential_ss(gsl_matrix, c_int(mode), result_gsl_matrix)

        result_matrix = GSLMatrix.gsl_matrix_to_numpy(result_gsl_matrix)
        return result_matrix
    except Exception as e:
        print('Error:', str(e))
        return None

