def find_min_max(matrix):
    n, m = len(matrix), len(matrix[0])
    matrix_sp = gsl.gsl_spmatrix_int_alloc(n, m)
    for i in range(n):
        for j in range(m):
            if matrix[i][j] != 0:
                gsl.gsl_spmatrix_int_set(matrix_sp, i, j, matrix[i][j])
    min_val = ctypes.c_int()
    max_val = ctypes.c_int()
    gsl.gsl_spmatrix_int_minmax(matrix_sp, ctypes.byref(min_val), ctypes.byref(max_val))
    gsl.gsl_spmatrix_int_free(matrix_sp)
    return (min_val.value, max_val.value)

