class GSLSpMatrix:
    def __init__(self, size):
        self.matrix = gsl.spmatrix_alloc(size, size)
        if not self.matrix:
            raise ValueError("Failed to allocate matrix")

    def populate(self, data):
        for i in range(len(data)):
            for j in range(len(data[i])):
                if data[i][j] != 0:
                    gsl.spmatrix_set(self.matrix, i, j, data[i][j])

    def get_data(self):
        size = self.size()
        data = [[0] * size for _ in range(size)]
        for i in range(size):
            for j in range(size):
                data[i][j] = gsl.spmatrix_get(self.matrix, i, j)
        return data

    def size(self):
        return ctypes.c_int.in_dll(gsl, "gsl_spmatrix_size")(self.matrix).value

