class GSLFunction(ctypes.Structure):
    _fields_ = [(\"x_minimum\", ctypes.c_double), (\"x_lower\", ctypes.c_double), (\"x_upper\", ctypes.c_double)]

def find_minimum(func, x_minimum, x_lower, x_upper):
    gsl_function_ptr = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(func)

    def wrapped_func(x):
        return gsl_function_ptr(x)

    func_ptr = ctypes.cast(ctypes.create_string_buffer(wrapped_func.__code__.co_code), ctypes.POINTER(ctypes.c_ubyte))

    result = gsl.gsl_min_fminimizer_set(gsl.GSL_MIN_FMINIMIZER_BRENT,
                                       ctypes.byref(GSLFunction(x_minimum, x_lower, x_upper)),
                                       func_ptr, ctypes.c_double(x_minimum),
                                       ctypes.c_double(x_lower), ctypes.c_double(x_upper))

    if result != 0:
        raise Exception(\"Failed to set minimizer\")

    for _ in range(100):
        result = gsl.gsl_min_fminimizer_iterate()
        if result != 0:
            raise Exception(\"Minimizer iteration failed\")

    x_minimum = gsl.gsl_min_fminimizer_x(gsl.get_min_fminimizer())
    f_minimum = gsl.gsl_min_fminimizer_f(gsl.get_min_fminimizer())

    return x_minimum, f_minimum

